nta.declaration:
// Place global declarations here.


/************************************************************
 *                     MAP CONSTANTS
 ************************************************************/

const int WIDTH  = 18;
const int HEIGHT = 13;

const int MAX_LIVES = 5;
const int NUM_HOME_BAYS = 5;

const int INITIAL_TIME_LIMIT = 300;   // 30 s

/************************************************************
 *                    ENUMERATIONS
 ************************************************************/

typedef int[0,3] TileType;

const TileType SAFE  = 0;
const TileType ROAD  = 1;
const TileType RIVER = 2;
const TileType HOME  = 3;

typedef int[0,4] ObjectType;

const ObjectType VEHICLE        = 0;
const ObjectType TRUCK          = 1;
const ObjectType LOG            = 2;
const ObjectType TURTLE         = 3;
const ObjectType DIVING_TURTLE  = 4;

/************************************************************
 *              IMMUTABLE OBJECT DESCRIPTION
 ************************************************************/

typedef struct
{
    int initialX;
    int row;            // fixed row
    int size;           // number of occupied cells
    int speed;          // movement period
    bool moveLeft;      // true = left, false = right
    ObjectType type;
    //int group;            //turtles may form a group. I still guess we can describe logs and regular turtles with the same type of the object, then there is no need for the group.
} ObjectInfo;

/************************************************************
 *              MUTABLE OBJECT STATE
 ************************************************************/

typedef struct
{
    int x;              // leftmost occupied cell
} ObjectState;

/************************************************************
 *                GAME STATE VARIABLES
 ************************************************************/

int frog_x = 9;
int frog_y = 0;

int score = 0;
int lives = MAX_LIVES;

bool bayOccupied[NUM_HOME_BAYS] =
{
    false,false,false,false,false
};

clock levelClock; //only for the game time out

/************************************************************
 *                 STATIC MAP
 ************************************************************/

const TileType map[HEIGHT] =
{
    SAFE,   // 0
    ROAD,   // 1
    ROAD,   // 2
    ROAD,   // 3
    ROAD,   // 4
    ROAD,   // 5
    SAFE,   // 6
    RIVER,  // 7
    RIVER,  // 8
    RIVER,  // 9
    RIVER,  //10
    RIVER,  //11
    HOME    //12
};

/************************************************************
 *              SYNCHRONIZATION CHANNELS
 ************************************************************/

chan moveHop;

broadcast chan frogDies;
broadcast chan reachBay;

/************************************************************
 *            OBJECT DECLARATIONS
 ************************************************************/


const int NUM_OBJECTS = 2;

const ObjectInfo objectInfo[NUM_OBJECTS] =
{
    // initialX,row,size,speed,left,type

    {4,1,1,3,true,VEHICLE},          // Orange car
    {14,1,1,3,true,VEHICLE}        // Orange car

};

ObjectState objectState[NUM_OBJECTS] =
{
    {4},
    {14}
};

bool is_object_at(int x, int y)
{
    return false;
}

// Returns true if Frogger is alive/safe at his current position
bool is_frogger_safe() {
    // 1. Out of horizontal bounds
    if (frog_x < 0 || frog_x >= WIDTH) return false;

    // 2. Safe Rows (Starting bank, Middle bank)
    if (frog_y == 0 || frog_y == 6) return true;

    // 3. Home Bays Row
    if (frog_y == 12) {
        // Safe only if he hits a valid bay index and it's not already full
        // (Assuming you map your 5 home bays to specific x coordinates)
        if (frog_x == 2 || frog_x == 6 || frog_x == 10 || frog_x == 14 || frog_x == 16) {
            int bay_idx = frog_x / 4; // Map x coordinate to bay index 0-4
            return !bayOccupied[bay_idx];
        }
        return false; // Hit the wall between bays
    }

    // 4. Highway Rows (1 to 5) -> Must NOT hit an object
    if (frog_y >= 1 && frog_y <= 5) {
        return !is_object_at(frog_x, frog_y);
    }

    // 5. River Rows (7 to 11) -> Must HIT an object (log/turtle)
    if (frog_y >= 7 && frog_y <= 11) {
        return is_object_at(frog_x, frog_y);
    }

    return false;
}

void moveObject(int id)
{
    if(objectInfo[id].moveLeft)
        objectState[id].x--;
    else
        objectState[id].x++;


}

bool leftScreen(int id)
{
    if(objectInfo[id].moveLeft)
        return objectState[id].x + objectInfo[id].size <= 0;

    return objectState[id].x >= WIDTH;
}

void respawnObject(int id)
{
    if(objectInfo[id].moveLeft)
        objectState[id].x = WIDTH;
    else
        objectState[id].x = -objectInfo[id].size;
}

